spec fn is_sign(x: i64, r: i64) -> bool { (x > 0 ==> r == 1) && (x < 0 ==> r == -1) && (x == 0 ==> r == 0) }

spec fn bounded(r: i64) -> bool { -1 <= r && r <= 1 }

#[effects(pure)]
#[uses(is_sign, bounded)]
fn sign(x: i64) -> (r: i64)
    ensures is_sign(x, r), bounded(r),
{
    2
}

